import json
import numpy as np

with open("train.json") as f:
    train = json.load(f)

# Inspect missingness across all rows in train
keys = ['time_min', 'age', 'mass', 'height', 'core_temp', 'skin_temp', 'hr', 'watts', 'ambient_temp', 'humidity']
counts = {k: 0 for k in keys}
null_counts = {k: 0 for k in keys}
total_rows = 0

for pid, rows in train.items():
    for r in rows:
        total_rows += 1
        for k in keys:
            if r.get(k) is None:
                null_counts[k] += 1
            else:
                counts[k] += 1

print(f"Total rows: {total_rows}")
for k in keys:
    print(f"{k:15s}: valid={counts[k]}, null={null_counts[k]} ({null_counts[k]/total_rows*100:.1f}%)")
"]}

