import json

with open("dev_requests.json") as f:
    dev = json.load(f)

for task in ['3B', '3A']:
    reqs = dev[task]
    keys = ['time_min', 'age', 'mass', 'height', 'skin_temp', 'hr', 'watts', 'ambient_temp', 'humidity']
    null_counts = {k: 0 for k in keys}
    total = 0
    for req in reqs:
        for r in req['history']:
            total += 1
            for k in keys:
                if r.get(k) is None:
                    null_counts[k] += 1
    print(f"Task {task}: total history rows {total}")
    for k in keys:
        print(f"  {k:15s}: null={null_counts[k]} ({null_counts[k]/total*100:.1f}%)")
"]}

