with open("train.json") as f: train = json.load(f)
with open("dev_requests.json") as f: dev = json.load(f)

dts_train = []
for pid, rows in train.items():
    for i in range(1, len(rows)):
        dts_train.append(rows[i]['time_min'] - rows[i-1]['time_min'])
print("Train dt set:", set(dts_train))

dts_dev = []
for req in dev['3B']:
    h = req['history']
    for i in range(1, len(h)):
        dts_dev.append(h[i]['time_min'] - h[i-1]['time_min'])
print("Dev dt set:", set(dts_dev))
